-- ★ 로그인 확인용 계정 (모든 샘플 계정의 공통 비밀번호) : Oncare2026!
--   관리자(시스템 관리자) : admin01
--   센터 관리자          : center01 (동대문), center02 (영등포), center03 (강남)
--   보호자               : guardian01 ~ guardian70 (guardian01 은 수급자 3명, 완료·배정완료·배정중·결원·취소 요청이 모두 있음)
--   요양보호사           : careworker01 ~ careworker100 (careworker01 은 확정·수락 대기·완료·취소 기록이 모두 있음)
--   요양보호사 가입 승인 확인용 : careworker95 ~ careworker98 은 승인대기 상태라 로그인되지 않고, 관리자 화면에 ✓ 표시가 뜬다.
--   탈퇴 확인용          : guardian70, careworker99 는 탈퇴(user_state = delete) 상태라 로그인되지 않는다.
--   결원 관리 확인용     : 요청 958번 (10/15, guardian01 의 수급자 이순자) 을 요양보호사 1번이 취소한 기록이 있다.
--   샘플 기준일은 2026-10-13 (화) 이다. 근무 기록은 9/13 ~ 이번 주, 근무 가능 시간은 10/13 ~ 다음 주(10/25) 까지 있다.

-- 서버를 켤 때마다(spring.sql.init.mode=always) 이 파일이 실행된다.
-- 테이블은 JPA 엔티티가 생성하고(ddl-auto=update), 상태 컬럼은 아래에서 존재 여부를 확인한다.
-- INSERT IGNORE : 이미 같은 번호(또는 같은 user_id)가 있으면 건너뛰어 재시작해도 오류가 나지 않는다.
--   → 이미 들어간 행은 이 파일을 고쳐도 바뀌지 않으므로, 번호를 바꿨다면 DB 를 비우고 다시 실행해야 한다.
-- 샘플을 추가할 때는 각 테이블의 마지막 번호 다음 번호를 쓰고, user_id 는 겹치지 않게 한다.
-- 위도/경도는 추천(거리 점수) 계산에 쓰이므로 주소를 카카오 지오코딩한 좌표를 함께 넣는다. 주소는 지오코딩이 되는 실제 도로명 주소를 쓴다.
-- 비밀번호는 모두 같은 BCrypt 해시이다.

-- 0. 예전 샘플 데이터 한 번 비우기
--   careworker100 계정이 없으면 예전 샘플이 들어 있는 DB 로 보고 모든 테이블의 행을 지운다.
--   아래에서 새 샘플을 넣으면 careworker100 이 생기므로 다음 실행부터는 아무것도 지우지 않는다.
--   테이블 구조는 그대로 두고 행만 지운다. (외래키 순서대로 자식 테이블부터)
SET SQL_SAFE_UPDATES = 0;
SET @reset_sample = IF(EXISTS (SELECT 1 FROM `user` WHERE user_id = 'careworker100'), 0, 1);
DELETE FROM careworkerreview WHERE @reset_sample = 1;
DELETE FROM chatmessage WHERE @reset_sample = 1;
DELETE FROM guardianinquiry WHERE @reset_sample = 1;
DELETE FROM careworkersreport WHERE @reset_sample = 1;
DELETE FROM caregiveravailability WHERE @reset_sample = 1;
DELETE FROM requests WHERE @reset_sample = 1;
DELETE FROM carerecipients WHERE @reset_sample = 1;
DELETE FROM careworkers WHERE @reset_sample = 1;
DELETE FROM guardians WHERE @reset_sample = 1;
DELETE FROM `user` WHERE @reset_sample = 1;
DELETE FROM center WHERE @reset_sample = 1;
DELETE FROM inquirycategory WHERE @reset_sample = 1;
DELETE FROM usercategory WHERE @reset_sample = 1;

-- 아이디 중복 방지 : 예전 샘플에 같은 user_id 가 있으면 JPA 가 unique 를 못 만들므로, 비운 뒤에 없으면 여기서 만든다.
SET @user_id_unique_ddl = IF(
    EXISTS (
        SELECT 1 FROM information_schema.STATISTICS
        WHERE TABLE_SCHEMA = DATABASE()
          AND TABLE_NAME = 'user'
          AND COLUMN_NAME = 'user_id'
          AND NON_UNIQUE = 0
    ),
    'SELECT 1',
    'ALTER TABLE `user` ADD CONSTRAINT UKa3imlf41l37utmxiquukk8ajc UNIQUE (user_id)'
);
PREPARE user_id_unique_statement FROM @user_id_unique_ddl;
EXECUTE user_id_unique_statement;
DEALLOCATE PREPARE user_id_unique_statement;

-- 보호자 상태 컬럼 추가: JPA가 이미 생성했거나 재실행하는 경우에는 건너뛴다.
SET @guardian_state_ddl = IF(
    EXISTS (
        SELECT 1 FROM information_schema.COLUMNS
        WHERE TABLE_SCHEMA = DATABASE()
          AND TABLE_NAME = 'guardians'
          AND LOWER(COLUMN_NAME) = 'guardian_state'
    ),
    'SELECT 1',
    'ALTER TABLE guardians ADD COLUMN guardian_State VARCHAR(20) NOT NULL DEFAULT ''use'''
);
PREPARE guardian_state_statement FROM @guardian_state_ddl;
EXECUTE guardian_state_statement;
DEALLOCATE PREPARE guardian_state_statement;

