-- 6-1. 예전 샘플 주소를 실제 주소로 바꾸기
--   예전 샘플의 요양보호사·수급자 주소는 동 단위(예: 서울특별시 동대문구 장안동)라 같은 동이면 지오코딩 좌표가 모두 같았고,
--   센터 1·3번 주소는 카카오 주소 검색에 나오지 않았다. 지금은 같은 동 안의 실제 주거지 도로명 주소와 그 지오코딩 좌표를 쓴다.
--   이미 샘플이 들어 있는 DB 는 INSERT IGNORE 로 바뀌지 않으므로, 주소가 예전 값 그대로인 행만 바꾼다. (화면에서 주소를 고친 행은 건드리지 않는다)
