INSERT IGNORE INTO guardianinquiry
(inquiry_no, guardian_no, inquiry_category_no, request_no, wish_date, wish_start_time, wish_end_time, inquiry_content, answer_content, answer_date, schedule_applied_date, inquiry_group, create_date, update_date) VALUES
(1, 21, 3, 59, NULL, NULL, NULL, '요양보호사님께 식사 간을 조금 싱겁게 해 달라고 전해 주세요.', NULL, NULL, NULL, NULL, '2026-09-17 17:40:00', '2026-09-17 17:40:00'),
(2, 62, 3, 191, NULL, NULL, NULL, '담당 요양보호사님이 너무 친절하셔서 계속 같은 분으로 부탁드립니다.', '다음 방문부터 요청하신 조건으로 배정하겠습니다.', '2026-09-19 09:45:00', NULL, NULL, '2026-09-18 13:40:00', '2026-09-19 09:45:00'),
(3, 9, 4, NULL, NULL, NULL, NULL, '방문 후 작성되는 돌봄 일지는 어디서 확인하나요?', NULL, NULL, NULL, NULL, '2026-09-18 14:40:00', '2026-09-18 14:40:00'),
(4, 24, 4, NULL, NULL, NULL, NULL, '복지용구(보행기) 대여도 센터에서 도와주시나요?', '평일 오전 9시부터 오후 6시까지 운영하며 대표번호로 연락 주시면 됩니다.', '2026-09-22 14:20:00', NULL, NULL, '2026-09-21 17:25:00', '2026-09-22 14:20:00'),
(5, 5, 4, NULL, NULL, NULL, NULL, '본인부담금 영수증을 발급받을 수 있을까요?', '네, 가능합니다. 자세한 절차는 전화로 안내드리겠습니다.', '2026-09-23 12:20:00', NULL, NULL, '2026-09-22 18:55:00', '2026-09-23 12:20:00'),
(6, 36, 3, 311, NULL, NULL, NULL, '어머니가 여자 요양보호사님을 더 편해하셔서 변경 가능할까요?', '다음 방문부터 요청하신 조건으로 배정하겠습니다.', '2026-09-24 15:00:00', NULL, NULL, '2026-09-23 10:00:00', '2026-09-24 15:00:00'),
(7, 11, 3, 336, NULL, NULL, NULL, '담당 선생님이 바뀌었는데 이유가 궁금합니다.', '확인해 보니 교통 사정으로 늦어졌다고 합니다. 재발하지 않도록 안내했습니다.', '2026-09-25 18:00:00', NULL, NULL, '2026-09-24 12:40:00', '2026-09-25 18:00:00'),
(8, 23, 4, NULL, NULL, NULL, NULL, '명절 연휴에도 방문 서비스가 가능한가요?', '평일 오전 9시부터 오후 6시까지 운영하며 대표번호로 연락 주시면 됩니다.', '2026-09-26 14:45:00', NULL, NULL, '2026-09-25 11:35:00', '2026-09-26 14:45:00'),
(9, 32, 4, NULL, NULL, NULL, NULL, '장기요양 등급 갱신은 어떻게 진행하나요?', '평일 오전 9시부터 오후 6시까지 운영하며 대표번호로 연락 주시면 됩니다.', '2026-09-26 16:05:00', NULL, NULL, '2026-09-25 15:00:00', '2026-09-26 16:05:00'),
(10, 39, 3, 386, NULL, NULL, NULL, '담당 선생님 연락처를 알 수 있을까요?', NULL, NULL, NULL, NULL, '2026-09-26 14:50:00', '2026-09-26 14:50:00'),
(11, 35, 4, NULL, NULL, NULL, NULL, '복지용구(보행기) 대여도 센터에서 도와주시나요?', '보호자 화면의 방문 기록 메뉴에서 확인하실 수 있습니다.', '2026-09-28 12:55:00', NULL, NULL, '2026-09-27 15:35:00', '2026-09-28 12:55:00'),
(12, 52, 3, 392, NULL, NULL, NULL, '담당 요양보호사님이 너무 친절하셔서 계속 같은 분으로 부탁드립니다.', '확인해 보니 교통 사정으로 늦어졌다고 합니다. 재발하지 않도록 안내했습니다.', '2026-09-28 20:55:00', NULL, NULL, '2026-09-27 18:45:00', '2026-09-28 20:55:00'),
(13, 48, 4, NULL, NULL, NULL, NULL, '본인부담금 영수증을 발급받을 수 있을까요?', NULL, NULL, NULL, NULL, '2026-09-28 09:15:00', '2026-09-28 09:15:00'),
(14, 18, 3, 402, NULL, NULL, NULL, '아버지 목욕 보조는 남자 요양보호사님이 해 주셨으면 합니다.', NULL, NULL, NULL, NULL, '2026-09-28 19:35:00', '2026-09-28 19:35:00'),
(15, 40, 3, 443, NULL, NULL, NULL, '요양보호사님께 식사 간을 조금 싱겁게 해 달라고 전해 주세요.', '확인해 보니 교통 사정으로 늦어졌다고 합니다. 재발하지 않도록 안내했습니다.', '2026-10-01 10:50:00', NULL, NULL, '2026-09-30 17:55:00', '2026-10-01 10:50:00'),
(16, 31, 4, NULL, NULL, NULL, NULL, '장기요양 등급 갱신은 어떻게 진행하나요?', '보호자 화면의 방문 기록 메뉴에서 확인하실 수 있습니다.', '2026-10-02 11:05:00', NULL, NULL, '2026-10-01 11:50:00', '2026-10-02 11:05:00'),
(17, 70, 4, NULL, NULL, NULL, NULL, '이사를 가게 되어 서비스 해지를 문의드립니다.', '해지 절차 안내드렸습니다. 그동안 이용해 주셔서 감사합니다.', '2026-10-02 15:40:00', NULL, NULL, '2026-10-02 10:20:00', '2026-10-02 15:40:00'),
(18, 28, 3, 555, NULL, NULL, NULL, '요양보호사님이 지난번 방문 때 10분 정도 늦으셨는데 확인 부탁드립니다.', '말씀하신 내용 담당 선생님께 전달했습니다. 감사합니다.', '2026-10-04 17:45:00', NULL, NULL, '2026-10-03 08:00:00', '2026-10-04 17:45:00'),
(19, 37, 4, NULL, NULL, NULL, NULL, '보호자를 한 명 더 등록할 수 있는지 궁금합니다.', NULL, NULL, NULL, NULL, '2026-10-03 18:05:00', '2026-10-03 18:05:00'),
(20, 59, 4, NULL, NULL, NULL, NULL, '앱에서 알림이 오지 않는데 설정을 확인해 주세요.', NULL, NULL, NULL, NULL, '2026-10-03 19:50:00', '2026-10-03 19:50:00'),
(21, 26, 1, 1094, '2026-10-20', 15, 18, '어머니가 오전에 복지관 프로그램에 가셔서 시간을 늦춰 주세요.', '희망 시간에 기존 선생님 일정이 맞지 않아 다른 선생님으로 배정을 변경했습니다.', '2026-10-11 14:40:00', '2026-10-11 14:40:00', 'G26-1791073500000', '2026-10-04 09:25:00', '2026-10-11 14:40:00'),
(22, 29, 1, 1058, '2026-10-19', 13, 17, '그날 가족 모임이 있어 방문을 조금 일찍 시작했으면 합니다.', '희망 시간에 기존 선생님 일정이 맞지 않아 다른 선생님으로 배정을 변경했습니다.', '2026-10-10 14:05:00', '2026-10-10 14:05:00', 'G29-1791084000000', '2026-10-04 12:20:00', '2026-10-10 14:05:00'),
(23, 64, 3, 604, NULL, NULL, NULL, '담당 선생님 연락처를 알 수 있을까요?', '다음 방문부터 요청하신 조건으로 배정하겠습니다.', '2026-10-05 16:55:00', NULL, NULL, '2026-10-04 15:00:00', '2026-10-05 16:55:00'),
(24, 53, 1, 1183, '2026-10-22', 10, 13, '정기 검진 때문에 오전 방문이 어렵습니다. 오후로 부탁드립니다.', '희망 시간에 기존 선생님 일정이 맞지 않아 다른 선생님으로 배정을 변경했습니다.', '2026-10-10 16:15:00', '2026-10-10 16:15:00', 'G53-1791110700000', '2026-10-04 19:45:00', '2026-10-10 16:15:00'),
(25, 17, 3, 608, NULL, NULL, NULL, '요양보호사님이 지난번 방문 때 10분 정도 늦으셨는데 확인 부탁드립니다.', '확인해 보니 교통 사정으로 늦어졌다고 합니다. 재발하지 않도록 안내했습니다.', '2026-10-06 18:20:00', NULL, NULL, '2026-10-05 08:40:00', '2026-10-06 18:20:00'),
(26, 68, 1, 955, '2026-10-14', 13, 17, '아버지 낮잠 시간과 겹쳐서 시간을 조정하고 싶어요.', '담당 요양보호사님과 확인 후 희망 시간으로 조정했습니다.', '2026-10-12 09:00:00', '2026-10-12 09:00:00', 'G68-1791160500000', '2026-10-05 09:35:00', '2026-10-12 09:00:00'),
(27, 12, 4, NULL, NULL, NULL, NULL, '방문 후 작성되는 돌봄 일지는 어디서 확인하나요?', NULL, NULL, NULL, NULL, '2026-10-05 15:00:00', '2026-10-05 15:00:00'),
(28, 41, 4, NULL, NULL, NULL, NULL, '수급자 주소가 이사로 바뀌는데 어떻게 변경하나요?', NULL, NULL, NULL, NULL, '2026-10-05 16:05:00', '2026-10-05 16:05:00'),
(29, 60, 4, NULL, NULL, NULL, NULL, '센터 운영 시간과 상담 전화번호가 궁금합니다.', '관련 서류는 센터 방문 시 바로 발급해 드립니다.', '2026-10-08 12:45:00', NULL, NULL, '2026-10-07 08:05:00', '2026-10-08 12:45:00'),
(30, 42, 3, 689, NULL, NULL, NULL, '새로 오신 선생님과 어머니가 잘 맞으셔서 감사 인사 드립니다.', '담당자 변경은 선생님 휴직으로 인한 것이며 이후 일정은 새 선생님이 계속 맡습니다.', '2026-10-08 15:45:00', NULL, NULL, '2026-10-07 08:15:00', '2026-10-08 15:45:00'),
(31, 6, 1, 920, '2026-10-14', 14, 17, '제가 퇴근 후에 함께 있을 수 있게 오후 늦게로 변경 부탁드립니다.', '요청하신 시간으로 방문 일정을 변경했습니다.', '2026-10-11 14:20:00', '2026-10-11 14:20:00', 'G6-1791369900000', '2026-10-07 19:45:00', '2026-10-11 14:20:00'),
(32, 56, 1, 946, '2026-10-14', 10, 14, '병원 동행이 필요해서 그날만 시간을 길게 잡아 주세요.', '희망 시간에 기존 선생님 일정이 맞지 않아 다른 선생님으로 배정을 변경했습니다.', '2026-10-12 17:20:00', '2026-10-12 17:20:00', 'G56-1791370200000', '2026-10-07 19:50:00', '2026-10-12 17:20:00'),
(33, 2, 1, 1084, '2026-10-20', 9, 13, '병원 예약이 잡혀서 방문 시간을 오후로 옮기고 싶습니다.', '담당 요양보호사님과 확인 후 희망 시간으로 조정했습니다.', '2026-10-11 10:45:00', '2026-10-11 10:45:00', 'G2-1791450300000', '2026-10-08 18:05:00', '2026-10-11 10:45:00'),
(34, 22, 3, 720, NULL, NULL, NULL, '어머니가 여자 요양보호사님을 더 편해하셔서 변경 가능할까요?', NULL, NULL, NULL, NULL, '2026-10-08 19:20:00', '2026-10-08 19:20:00'),
(35, 55, 1, 1108, '2026-10-20', 15, 19, '주간보호센터 귀가 시간이 바뀌어 방문 시간도 맞춰 주세요.', '담당 요양보호사님과 확인 후 희망 시간으로 조정했습니다.', '2026-10-11 09:30:00', '2026-10-11 09:30:00', 'G55-1791456900000', '2026-10-08 19:55:00', '2026-10-11 09:30:00'),
(36, 25, 4, NULL, NULL, NULL, NULL, '방문 요양 외에 방문 목욕 서비스도 신청할 수 있나요?', NULL, NULL, NULL, NULL, '2026-10-09 10:05:00', '2026-10-09 10:05:00'),
(37, 51, 2, 991, '2026-10-15', 9, 11, '월요일에 정기 외래가 생겨서 다른 요일로 변경 부탁드립니다.', '해당 날짜는 배정 가능한 인원이 부족해 다른 날짜를 안내드리겠습니다. 센터로 연락 부탁드립니다.', '2026-10-10 11:35:00', NULL, 'G51-1791543600000', '2026-10-09 20:00:00', '2026-10-10 11:35:00'),
